import{_ as o}from"./chunks/02.CDe4raOw.js";import{_ as t,o as d,c as r,aa as n,j as a}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/den-v-deniku/01.webp",s="/buildary-help-preview/media/cs/diary/pocty_podpisu_2.png",p="/buildary-help-preview/media/cs/diary/poznamky2.png",l="/buildary-help-preview/academy/img/nepracovni-dny/03.webp",g=JSON.parse('{"title":"Denní záznamy","description":"","frontmatter":{"title":"Denní záznamy","wiki":"cs:diary:dailyentries"},"headers":[],"relativePath":"diary/dailyentries.md","filePath":"diary/dailyentries.md","lastUpdated":1794209661000}'),k={name:"diary/dailyentries.md"};function v(z,e,m,u,y,h){return d(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="denni-zaznamy" tabindex="-1">Denní záznamy <a class="header-anchor" href="#denni-zaznamy" aria-label="Permalink to &quot;Denní záznamy&quot;">​</a></h1><p>Do deníku zapisujete po dnech. Okno <strong>Denní záznamy</strong> ukazuje vždy jeden den: jeho stav, záznamy rozdělené do sekcí a volby pro práci s celým dnem. Hotový den podpisem uzamknete a vznikne z něj Denní protokol v PDF.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/den-v-deniku">Pochopit, jak funguje den v deníku</a>, <a href="/buildary-help-preview/akademie/nepracovni-dny">Označit víkend nebo svátek jako nepracovní</a> a <a href="/buildary-help-preview/akademie/zamceni-dne">Dočasně zamknout den proti úpravám</a> v Akademii.</p>',3),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/NoaEqtiXXms",title:"Video: Denní záznamy",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),n('<h2 id="okno-denni-zaznamy" tabindex="-1">Okno Denní záznamy <a class="header-anchor" href="#okno-denni-zaznamy" aria-label="Permalink to &quot;Okno Denní záznamy&quot;">​</a></h2><p>Okno otevřete v levém panelu volbou <strong>Denní záznamy</strong>. Otevře se vždy na dnešním dni.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Okno Denní záznamy s kalendářní lištou, tlačítky dne a sekcí Počasí" loading="lazy"></figure><ul><li><strong>Kalendářní lišta</strong> nahoře ukazuje dny týdne. Kliknutím na den ho otevřete, šipkami po stranách lišty se posunete na předchozí nebo další dny.</li><li><strong>Ikona kalendáře</strong> vedle data otevře kalendář, ve kterém vyberete libovolný den.</li><li><strong>Sbalit</strong> sbalí všechny sekce dne – hodí se pro rychlý přehled.</li><li><strong>Náhled PDF</strong> ukáže den tak, jak bude vypadat v Denním protokolu.</li><li><strong>Podepsat</strong> podepíše a uzamkne celý den – viz <a href="#podepsat-den">Podepsat den</a>.</li><li><strong>Další volby</strong> nabízí akce pro celý den – viz <a href="#dalsi-volby-dne">Další volby dne</a>.</li></ul><p>Nad lištou jsou tlačítka pro celý deník: <strong>Vyhledávání</strong> (viz <a href="/buildary-help-preview/diary/download#vyhledat-v-deniku">Vyhledat v deníku</a>), <strong>Nastavení deníku</strong> a <strong>Exporty</strong> (viz <a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>).</p><h2 id="co-znamenaji-barvy-a-ikony-dne" tabindex="-1">Co znamenají barvy a ikony dne <a class="header-anchor" href="#co-znamenaji-barvy-a-ikony-dne" aria-label="Permalink to &quot;Co znamenají barvy a ikony dne&quot;">​</a></h2><p>Pod každým dnem v kalendářní liště je barevný pruh. Říká, v jakém stavu den je.</p><table tabindex="0"><thead><tr><th>Barva</th><th>Stav dne</th></tr></thead><tbody><tr><td>Červená</td><td>Den není podepsaný a zatím v něm nejsou žádné záznamy.</td></tr><tr><td>Modrá</td><td>Den obsahuje záznamy, ale není podepsaný ani zamčený.</td></tr><tr><td>Fialová</td><td>Den je <a href="#docasne-zamknout-den">uživatelsky zamčený</a>. Zámek jde zrušit.</td></tr><tr><td>Žlutá</td><td>Den se právě podepisuje a je dočasně zamčený.</td></tr><tr><td>Zelená</td><td>Den je podepsaný a trvale uzamčený.</td></tr><tr><td>Šedá</td><td><a href="#nepracovni-den">Nepracovní den</a> – bez záznamů a uzamčený.</td></tr></tbody></table><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Kalendářní lišta s barevnými pruhy, ikonami poznámek a počtem podpisů u jednotlivých dnů" loading="lazy"></figure><p>Pod datem jsou u každého dne tři ikony:</p><ul><li><strong>Oranžová bublina</strong> – ke dni je veřejná poznámka.</li><li><strong>Modrá bublina</strong> – ke dni je vaše soukromá poznámka.</li><li><strong>Číslo</strong> – počet elektronických podpisů Denního protokolu. U podepsaného dne je zelené.</li></ul><p>Šedá bublina znamená, že poznámka daného typu chybí.</p><h2 id="poznamky-ke-dni" tabindex="-1">Poznámky ke dni <a class="header-anchor" href="#poznamky-ke-dni" aria-label="Permalink to &quot;Poznámky ke dni&quot;">​</a></h2><p>Ke každému dni si můžete zapsat poznámku. Poznámka ke dni není součástí deníku – do Denního protokolu ani do PDF se nepropíše. Hodí se třeba na připomínky, co je potřeba ten den ještě doplnit.</p><p>Poznámku otevřete v <strong>Dalších volbách</strong> volbou <strong>Poznámky</strong>. V okně <strong>Poznámky ke dni</strong> jsou dvě pole, obě můžete i nadiktovat tlačítkem <strong>Nadiktovat</strong>:</p><ul><li><strong>Veřejná poznámka</strong> – vidí ji všechny oprávněné osoby deníku.</li><li><strong>Soukromá poznámka</strong> – vidíte ji jen vy.</li></ul><p>Poznámky může vkládat každý, kdo má v deníku právo zapisovat.</p><figure class="shot" style="--w:560px;"><img src="'+p+'" alt="Okno Poznámky ke dni s polem Veřejná poznámka a Soukromá poznámka" loading="lazy"></figure><h2 id="sekce-dne" tabindex="-1">Sekce dne <a class="header-anchor" href="#sekce-dne" aria-label="Permalink to &quot;Sekce dne&quot;">​</a></h2><p>Záznamy dne jsou rozdělené do sekcí. Pořadí sekcí, jejich názvy a pole, která se v nich vyplňují, nastavuje administrátor deníku v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a>.</p><table tabindex="0"><thead><tr><th>Sekce</th><th>Co do ní patří</th><th>Podrobně</th></tr></thead><tbody><tr><td><strong>Počasí</strong></td><td>Počasí v nastavených hodinách, poznámka k počasí.</td><td><a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a></td></tr><tr><td><strong>Osoby na staveništi</strong></td><td>Kdo byl na stavbě, profese, dodavatel, počty osob a hodin.</td><td><a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a></td></tr><tr><td><strong>Mechanizmy</strong></td><td>Stroje a technika na stavbě.</td><td><a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a></td></tr><tr><td><strong>Materiály, výrobky a technologické dodávky</strong></td><td>Dodaný materiál včetně čísla dodacího listu.</td><td><a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a></td></tr><tr><td><strong>Provedené práce</strong></td><td>Co se ten den na stavbě udělalo.</td><td><a href="/buildary-help-preview/diary/dailyentriesworks">Provedené práce</a></td></tr><tr><td><strong>Další záznamy</strong></td><td>Výzvy, kontroly, předávky, připomínky dozoru.</td><td><a href="/buildary-help-preview/diary/dailyentriesothers">Další záznamy</a></td></tr></tbody></table><p>V sekcích najdete tlačítko <strong>Přidat záznam</strong>, ve většině z nich také <strong>Kopírovat záznamy</strong> (převezme záznamy z jiného dne – viz <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>) a <strong>Přidat poznámku</strong> k sekci.</p><div class="info custom-block"><p class="custom-block-title">Kdo může záznam změnit</p><p>Každý uživatel může upravit nebo smazat jen záznamy, které sám vložil – a jen do doby, než je den nebo záznam uzamčený. Záznamy jiného uživatele nezmění nikdo, bez ohledu na nastavená oprávnění.</p></div><p>Záznamy zapisujte a podepisujte průběžně – zákonnou lhůtu pro zápis a to, jak ji Buildary hlídá, popisuje <a href="/buildary-help-preview/diary/diarysettings#cas-porizeni-zaznamu">Čas pořízení záznamu</a>.</p><h2 id="dalsi-volby-dne" tabindex="-1">Další volby dne <a class="header-anchor" href="#dalsi-volby-dne" aria-label="Permalink to &quot;Další volby dne&quot;">​</a></h2><p>Menu <strong>Další volby</strong> vpravo nad sekcemi obsahuje akce pro otevřený den. Některé volby jsou šedé, když je v daném stavu dne nelze použít.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Rozbalené menu Další volby dne" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Volba</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Náhled denního záznamu</strong></td><td>Zobrazí Denní protokol v prohlížeči.</td></tr><tr><td><strong>Stažení denního záznamu</strong></td><td>Stáhne Denní protokol jako PDF.</td></tr><tr><td><strong>Podepsat více dní</strong></td><td>Podepíše najednou několik po sobě jdoucích dnů – viz <a href="/buildary-help-preview/diary/signing#podepsat-vice-dni-najednou">Podepsat více dní najednou</a>.</td></tr><tr><td><strong>Kopíruj den</strong></td><td>Převezme záznamy z jiného dne tohoto deníku.</td></tr><tr><td><strong>Kopíruj z propojených deníků</strong></td><td>Převezme záznamy z deníků podzhotovitelů.</td></tr><tr><td><strong>Kopíruj z deníků částí staveb</strong></td><td>Převezme provedené práce z deníků částí stavby.</td></tr><tr><td><strong>Poznámky</strong></td><td>Otevře <a href="#poznamky-ke-dni">poznámky ke dni</a>.</td></tr><tr><td><strong>Uživatelské zamčení dne</strong></td><td>Dočasně zamkne den proti úpravám.</td></tr><tr><td><strong>Nepracovní den (bez záznamů)</strong></td><td>Označí den nebo více dnů jako nepracovní.</td></tr></tbody></table><p>Všechny tři způsoby kopírování popisuje stránka <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>.</p><h2 id="nepracovni-den" tabindex="-1">Nepracovní den <a class="header-anchor" href="#nepracovni-den" aria-label="Permalink to &quot;Nepracovní den&quot;">​</a></h2><p>Nepracovní den je den bez záznamů, ve kterém je to v pořádku: víkend, svátek, technologická přestávka nebo přerušení prací. Takový den musíte jako nepracovní označit – jinak nepůjde podepsat žádný den po něm.</p><p>Podepsat lze jen den, před kterým jsou všechny dny uzavřené, tedy podepsané, nebo označené jako nepracovní. Stránky deníku se totiž číslují postupně.</p><ol><li>Otevřete den a v <strong>Dalších volbách</strong> zvolte <strong>Nepracovní den (bez záznamů)</strong>.</li><li>V okně <strong>Nepracovní den bez záznamu</strong> zadejte rozsah dnů do polí <strong>Od</strong> a <strong>Do</strong>. Tlačítko <strong>Zadat víkend</strong> vyplní sobotu a neděli.</li><li>Klikněte na <strong>Nastavit</strong> a akci potvrďte.</li></ol><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="Okno Nepracovní den bez záznamu s poli Od a Do a tlačítkem Zadat víkend" loading="lazy"></figure><div class="danger custom-block"><p class="custom-block-title">Záznamy dne se smažou</p><p>Označením dne za nepracovní se smažou všechny záznamy, které v zadaném období jsou. Akci nelze vrátit zpět.</p></div><p>Nepracovní den má v kalendářní liště šedý pruh. Den, který je už podepsaný, za nepracovní označit nejde.</p><p>Nepracovní den můžete změnit zpět na pracovní, dokud není podepsaný některý den po něm.</p><h2 id="docasne-zamknout-den" tabindex="-1">Dočasně zamknout den <a class="header-anchor" href="#docasne-zamknout-den" aria-label="Permalink to &quot;Dočasně zamknout den&quot;">​</a></h2><p>Uživatelským zámkem dočasně zabráníte úpravám dne – třeba když ho mají kolegové zkontrolovat před podpisem.</p><ul><li>Den zamknete v <strong>Dalších volbách</strong> volbou <strong>Uživatelské zamčení dne</strong>. V kalendářní liště dostane fialový pruh.</li><li>Zámek zrušíte volbou <strong>Zruš uživatelské zamčení dne</strong>.</li></ul><p>Uživatelský zámek nenahrazuje podpis. Den zůstává nepodepsaný a zámek jde kdykoli zrušit.</p><h2 id="podepsat-den" tabindex="-1">Podepsat den <a class="header-anchor" href="#podepsat-den" aria-label="Permalink to &quot;Podepsat den&quot;">​</a></h2><p>Den podepíšete tlačítkem <strong>Podepsat</strong> – podpisem se trvale uzamkne a v kalendářní liště dostane zelený pruh. Více dnů najednou podepíšete v <strong>Dalších volbách</strong> volbou <strong>Podepsat více dní</strong>, viz <a href="/buildary-help-preview/diary/signing#podepsat-vice-dni-najednou">Podepsat více dní najednou</a>.</p><p>Jak podpis funguje, kdo podepisuje a jaké jsou způsoby podpisu, popisuje <a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>.</p><div class="tip custom-block"><p class="custom-block-title">Den nejde podepsat?</p><p>Zkontrolujte, jestli nejsou předchozí dny nepodepsané nebo neoznačené jako nepracovní.</p></div>',45)])])}const j=t(k,[["render",v]]);export{g as __pageData,j as default};
